import{_ as a,o as l,c as p,am as e}from"./chunks/framework._FJXuPhs.js";const g=JSON.parse('{"title":"面试煎熬成蛋_JVM","description":"","frontmatter":{"title":"面试煎熬成蛋_JVM","excerpt":"面试煎熬成蛋_JVM","date":"2024-03-10 19:35:20","updated":"2024-03-10 19:35:20"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_JVM.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_JVM.md","lastUpdated":null}'),o={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_Java基础/面试煎熬成蛋_JVM.md"};function n(s,i,t,c,r,u){return l(),p("div",null,[...i[0]||(i[0]=[e('<ul><li>1、JVM是什么，讲一下运行流程</li><li>2、什么是程序计数器</li><li>3、介绍一下堆</li><li>4、什么是虚拟机栈</li><li>5、讲一下方法区</li><li>6、听过直接内存吗</li><li>7、什么是类加载器，什么是双亲委派机制</li><li>8、说一下类加载的执行过程</li><li>9、对象什么时候可以被垃圾器回收</li><li>10、JVM 垃圾回收算法有哪些</li><li>11、说一下 JVM 的分代回收</li><li>12、说一下 JVM 有哪些垃圾回收器</li><li>13、详细聊一下 G1 垃圾回收器</li><li>14、强引用、弱引用、软引用、虚引用的区别</li><li>15、JVM调优参数可以在哪里设置参数值</li><li>16、用的JVM调优的参数都有哪些</li><li>17、说一下 JVM 调优的工具</li><li>18、JVM 内存泄漏的排查思路</li><li>19、CPU 飙高的排查方案及其思路</li></ul><h3 id="jvm-组成" tabindex="-1">JVM 组成 <a class="header-anchor" href="#jvm-组成" aria-label="Permalink to &quot;JVM 组成&quot;">​</a></h3><h4 id="jvm-是-什么" tabindex="-1">JVM 是 什么 <a class="header-anchor" href="#jvm-是-什么" aria-label="Permalink to &quot;JVM 是 什么&quot;">​</a></h4><p>Java Virtul Machine：Java 程序的运行环境</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305151245.png" alt="image.png"></p><h4 id="jvm-组成-1" tabindex="-1">JVM 组成 <a class="header-anchor" href="#jvm-组成-1" aria-label="Permalink to &quot;JVM 组成&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305151409.png" alt="image.png"></p><h4 id="程序计数器" tabindex="-1">程序计数器 <a class="header-anchor" href="#程序计数器" aria-label="Permalink to &quot;程序计数器&quot;">​</a></h4><p>程序计数器：用于记录正在执行的字节码指令的地址。</p><p>什么是程序计数器？</p><ul><li>线程私有的，每个线程一份，内部保存的字节码的行号。用于记录正在执行的字节码指令的地址。</li></ul><h4 id="java-堆" tabindex="-1">Java 堆 <a class="header-anchor" href="#java-堆" aria-label="Permalink to &quot;Java 堆&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305152210.png" alt="image.png"></p><p>你能给我详细的介绍Java堆吗？</p><ul><li><p>线程共享的区域：主要用来保存对象实例，数组等，内存不够则抛出 OutOfMemoryError异常。</p></li><li><p>组成：年轻代+老年代</p><ul><li>年轻代被划分为三部分，Eden区 和 两个大小严格相同的 Survivor 区</li><li>老年代主要保存生命周期长的对象，一般是一些老的对象</li></ul></li><li><p>Jdk1.7和1.8的区别</p><ul><li>1.7中有有一个永久代，存储的是类信息、静态变量、常量、编译后的代码</li><li>1.8移除了永久代，把数据存储到了本地内存的元空间中，防止内存溢出</li></ul></li></ul><h4 id="讲一下老年代和年轻代-🚩" tabindex="-1">讲一下老年代和年轻代 🚩 <a class="header-anchor" href="#讲一下老年代和年轻代-🚩" aria-label="Permalink to &quot;讲一下老年代和年轻代  🚩&quot;">​</a></h4><ul><li>堆中区域（用于垃圾回收，垃圾回收主要针对的是堆这个区域）【基于对象生命周期划分】 <ul><li>年轻代 <ul><li>Eden空间 <ul><li>大部分新生成的对象都会首先在Eden空间分配。当Eden空间填满时，会触发一次Minor GC（也称为Young GC），清理掉不再被引用的对象。</li></ul></li><li>两个幸存者空间（Survivor Spaces）：分别称为S0（From Space）和S1（To Space） <ul><li>在Minor GC过程中，从Eden空间和一个Survivor空间（例如S0）幸存下来的对象，如果仍然被引用，会被移动到另一个Survivor空间（例如S1）。在每次Minor GC之后，这两个Survivor空间的角色会互换。</li></ul></li></ul></li><li>老年代 <ul><li>老年代用于存放长时间存活的对象。一般来说，当对象在年轻代经历了多次GC还存活时，它们会被晋升到老年代。老年代的空间比年轻代大得多，当它被填满时，会触发Major GC（也称为Full GC），这个过程比Minor GC要慢得多。</li></ul></li></ul></li><li>垃圾收集过程 <ul><li><strong>Minor GC</strong>：清理年轻代。因为年轻代中的对象大多是短暂的，所以Minor GC相对频繁，但速度快。</li><li><strong>Major GC / Full GC</strong>：清理整个堆，包括年轻代和老年代。这个过程比Minor GC慢，因为它需要检查堆中的所有对象。</li></ul></li></ul><p>GC策略和算法</p><p>不同的垃圾收集器有不同的实现方式和优化策略。例如，串行收集器（Serial GC）、并行收集器（Parallel GC）、并发标记清除（CMS GC）和G1收集器（G1 GC）等，它们在处理年轻代和老年代的垃圾时使用不同的算法和策略。</p><h4 id="虚拟机栈" tabindex="-1">虚拟机栈 <a class="header-anchor" href="#虚拟机栈" aria-label="Permalink to &quot;虚拟机栈&quot;">​</a></h4><p>什么是虚拟机栈</p><ul><li>每个线程运行时所需要的内存，成为虚拟机栈</li><li>每个栈由多个栈帧（frame）组成，对应着每次方法调用时所占用的内存</li><li>每个线程只能有一个活动栈帧，对应着当前正在执行的那个方法</li></ul><h4 id="垃圾回收是否涉及栈内存" tabindex="-1">垃圾回收是否涉及栈内存 <a class="header-anchor" href="#垃圾回收是否涉及栈内存" aria-label="Permalink to &quot;垃圾回收是否涉及栈内存&quot;">​</a></h4><ul><li>垃圾回收主要指就是堆内存，当栈帧弹栈以后，内存就会释放</li></ul><h4 id="栈内存分配越大越好吗" tabindex="-1">栈内存分配越大越好吗 <a class="header-anchor" href="#栈内存分配越大越好吗" aria-label="Permalink to &quot;栈内存分配越大越好吗&quot;">​</a></h4><ul><li>未必，默认的栈内存通常为 1024 K, 栈帧过大会导致线程数变少</li></ul><h4 id="方法内的局部变量是否线程安全" tabindex="-1">方法内的局部变量是否线程安全 <a class="header-anchor" href="#方法内的局部变量是否线程安全" aria-label="Permalink to &quot;方法内的局部变量是否线程安全&quot;">​</a></h4><ul><li>如果方法内局部变量没有逃离方法的作用范围，他是线程安全的</li><li>如果是局部变量引用了对象，并逃离方法的作用范围，需要考虑线程安全</li></ul><h4 id="什么情况下会导致栈内存溢出" tabindex="-1">什么情况下会导致栈内存溢出 <a class="header-anchor" href="#什么情况下会导致栈内存溢出" aria-label="Permalink to &quot;什么情况下会导致栈内存溢出&quot;">​</a></h4><ul><li>1、栈帧过多导致内存溢出，典型问题：递归调用</li><li>2、栈帧过大导致栈内存溢出</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305152825.png" alt="image.png"></p><h4 id="堆栈的区别-是-什么" tabindex="-1">堆栈的区别 是 什么 <a class="header-anchor" href="#堆栈的区别-是-什么" aria-label="Permalink to &quot;堆栈的区别 是 什么&quot;">​</a></h4><ul><li>栈内存一般会用来存储局部变量和方法调用，但堆内存是用来存储va对象和数组的的。</li><li>堆会GC垃圾回收，而栈不会。</li><li>栈内存是线程私有的，而堆内存是线程共有的。</li><li>两者异常错误不同，但如果栈内存或者堆内存不足都会抛出异常 <ul><li>栈空间不足：java.lang.StackOverFlowError。</li><li>堆空间不足：java.lang.OutOfMemoryError。</li></ul></li></ul><h4 id="方法区" tabindex="-1">方法区 <a class="header-anchor" href="#方法区" aria-label="Permalink to &quot;方法区&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305162830.png" alt="image.png"></p><h4 id="运行时常量池" tabindex="-1">运行时常量池 <a class="header-anchor" href="#运行时常量池" aria-label="Permalink to &quot;运行时常量池&quot;">​</a></h4><p>常量池</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163117.png" alt="image.png"></p><p>运行时常量池</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163147.png" alt="image.png"></p><p>总结（方法区）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163227.png" alt="image.png"></p><h4 id="直接内存" tabindex="-1">直接内存 <a class="header-anchor" href="#直接内存" aria-label="Permalink to &quot;直接内存&quot;">​</a></h4><p>先看一下普通 IO 和 NIO 的数据拷贝图示区别</p><p>普通 IO</p><p>使用常规 IO 进行数据拷贝的时候，需要使用到 Java 缓冲区 和 操作系统的 系统缓存区的两个缓存区的数据交互（Java 不能直接访问系统缓存区，两个缓存区之间有一个数据复制耗时）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163718.png" alt="image.png"></p><p>NIO</p><p>提供了一个直接内存（Java 能直接访问）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163657.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305163930.png" alt="image.png"></p><h4 id="在1-8-中-运行时常量池是放置在哪个区域" tabindex="-1">在1.8 中，运行时常量池是放置在哪个区域？ <a class="header-anchor" href="#在1-8-中-运行时常量池是放置在哪个区域" aria-label="Permalink to &quot;在1.8 中，运行时常量池是放置在哪个区域？&quot;">​</a></h4><p>在Java 8中，<strong>字符串常量池</strong>已经被移动到了<strong>堆内存</strong>中，以提高性能和减少内存溢出的风险。</p><p>而<strong>运行时常量池</strong>除了字符串常量外的部分，仍然存储在方法区中，但方法区的实现已从永久代变更为<strong>元空间</strong>。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240315210151.png" alt="image.png"></p><h3 id="类加载器" tabindex="-1">类加载器 <a class="header-anchor" href="#类加载器" aria-label="Permalink to &quot;类加载器&quot;">​</a></h3><h4 id="类加载器-1" tabindex="-1">类加载器 <a class="header-anchor" href="#类加载器-1" aria-label="Permalink to &quot;类加载器&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305164418.png" alt="image.png"></p><h4 id="双亲委派机制" tabindex="-1">双亲委派机制 <a class="header-anchor" href="#双亲委派机制" aria-label="Permalink to &quot;双亲委派机制&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305164609.png" alt="image.png"></p><h4 id="类装载的过程" tabindex="-1">类装载的过程 <a class="header-anchor" href="#类装载的过程" aria-label="Permalink to &quot;类装载的过程&quot;">​</a></h4><p>总体的一个过程：加载 → 验证 → 准备 → 解析 → 初始化 → 使用 → 卸载</p><p>加载</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305164809.png" alt="image.png"></p><p>验证</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305164938.png" alt="image.png"></p><p>准备</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305165107.png" alt="image.png"></p><p>解析：把类中的符号引用转换为直接引用</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305165526.png" alt="image.png"></p><p>初始化：对类的静态变量，静态代码块执行初始化操作。</p><p>初始化的时候关于子类和父类以及静态变量的加载顺序可能要注意一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305165711.png" alt="image.png"></p><p>使用： JVM 开始从入口方法开始执行用户的程序代码。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305165803.png" alt="image.png"></p><p>卸载：当用户程序代码执行完毕后，JVM便开始销毁创建的 Class 对象。</p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305165216.png" alt="image.png"></p><h3 id="垃圾回收" tabindex="-1">垃圾回收 <a class="header-anchor" href="#垃圾回收" aria-label="Permalink to &quot;垃圾回收&quot;">​</a></h3><h4 id="垃圾回收机制总结" tabindex="-1">垃圾回收机制总结 <a class="header-anchor" href="#垃圾回收机制总结" aria-label="Permalink to &quot;垃圾回收机制总结&quot;">​</a></h4><p>Java Virtual Machine</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202401231557879.png" alt="image.png"></p><h4 id="对象什么时候可以被垃圾器回收-🚩" tabindex="-1">对象什么时候可以被垃圾器回收 🚩 <a class="header-anchor" href="#对象什么时候可以被垃圾器回收-🚩" aria-label="Permalink to &quot;对象什么时候可以被垃圾器回收 🚩&quot;">​</a></h4><p>判断对象是垃圾，则进行回收</p><p>回收确认垃圾的方式有两种：</p><ul><li>引用计数法</li><li>可达性分析算法</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305173256.png" alt="image.png"></p><p>引用计数法</p><p>引用计数法：一个对象被引用了一次，在当前的对象头上递增一次引用次数，如果这个对象的引用次数为0，代表这个对象可回收</p><ul><li>问题：当对象间出现了循环引用，则引用技术法会失效（两个的引用次数都不是0，不使用的时候引用次数互相为 1）</li></ul><blockquote><p>可达性分析算法</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305173812.png" alt="image.png"></p><h4 id="哪些对象可以作为-gc-root" tabindex="-1">哪些对象可以作为 GC Root ？ <a class="header-anchor" href="#哪些对象可以作为-gc-root" aria-label="Permalink to &quot;哪些对象可以作为 GC Root ？&quot;">​</a></h4><ul><li>虚拟机栈中（栈帧中的本地变量表）中引用的对象</li><li>方法区中类静态属性引用的对象</li><li>方法区中常量引用的对象</li><li>本地方法栈中 JNI 引用的对象</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305173900.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305173920.png" alt="image.png"></p><hr><h4 id="垃圾回收算法有哪些-🚩" tabindex="-1">垃圾回收算法有哪些 🚩 <a class="header-anchor" href="#垃圾回收算法有哪些-🚩" aria-label="Permalink to &quot;垃圾回收算法有哪些 🚩&quot;">​</a></h4><ul><li>标记清除算法</li><li>复制算法</li><li>标识整理算法</li></ul><blockquote><p>标记清除算法</p></blockquote><p>（使用较少）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305174057.png" alt="image.png"></p><blockquote><p>标记整理算法</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305174152.png" alt="image.png"></p><blockquote><p>复制算法</p></blockquote><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305174224.png" alt="image.png"></p><p>总结：</p><ul><li>标记清除算法（使用较少，会产生内存碎片）</li><li>标识整理算法（老年代用这种方式回收多一些）</li><li>复制算法（新生代用这种方式回收多一些）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305174310.png" alt="image.png"></p><hr><h4 id="说一下-jvm-的分代回收" tabindex="-1">说一下 JVM 的分代回收 <a class="header-anchor" href="#说一下-jvm-的分代回收" aria-label="Permalink to &quot;说一下 JVM 的分代回收&quot;">​</a></h4><p>工作机制</p><ul><li>1、新创建的对象，都会先分配到 eden 区</li><li>2、当伊甸园内存不足，标记伊甸园与 from(现阶段没有) 的存活对象</li><li>3、将存活对象采用复制算法复制到to中，复制完毕后，伊甸园和 from内存都得到释放</li><li>4、经过一段时间后伊甸园的内存又出现不足，标记eden区域to区存活的对象，将存活的对象复制到from区</li><li>5、当幸存区对象熬过几次回收（最多15次)，晋升到老年代（幸存区内存不足或大对象会导致提前晋升）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305174530.png" alt="image.png"></p><h4 id="minorgc、mixed-gc、fullgc-的区别是什么" tabindex="-1">MinorGC、Mixed GC、FullGC 的区别是什么？ <a class="header-anchor" href="#minorgc、mixed-gc、fullgc-的区别是什么" aria-label="Permalink to &quot;MinorGC、Mixed GC、FullGC 的区别是什么？&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175024.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175134.png" alt="image.png"></p><hr><h4 id="讲一下常用的垃圾回收器" tabindex="-1">讲一下常用的垃圾回收器 <a class="header-anchor" href="#讲一下常用的垃圾回收器" aria-label="Permalink to &quot;讲一下常用的垃圾回收器&quot;">​</a></h4><p>在 jvm 中，实现了多种垃圾收集器，包括：</p><ul><li>串行垃圾收集器</li><li>并行垃圾收集器</li><li>CMS(并发)垃圾收集器</li><li>G1垃圾收集器</li></ul><p>串行垃圾收集器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175345.png" alt="image.png"></p><p>并行垃圾收集器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175531.png" alt="image.png"></p><p>CMS(并发)垃圾收集器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175707.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175748.png" alt="image.png"></p><hr><h4 id="讲一下-g1-垃圾收集器" tabindex="-1">讲一下 G1 垃圾收集器 <a class="header-anchor" href="#讲一下-g1-垃圾收集器" aria-label="Permalink to &quot;讲一下 G1 垃圾收集器&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305175902.png" alt="image.png"></p><p>Young Collection(年轻代垃圾回收)</p><ul><li>1、初始时，所有区域都处于空闲状态</li><li>2、创建了一些对象，挑出一些空闲区域作为伊甸园区存储这些对象</li><li>3、当伊甸园需要垃圾回收时，挑出一个空闲区域作为幸存区，用复制算法复制存活对象，需要暂停用户线程</li><li>5、随着时间流逝，伊甸园的内存又有不足</li><li>6、将伊甸园以及之前幸存区中的存活对象，采用复制算法，复制到新的幸存区，其中较老对象晋升至老年代</li></ul><p>Young Collection+Concurrent Mark(年轻代垃圾回收+并发标记)</p><ul><li><p>当老年代占用内存超过阈值（默认是45%）后，触发并发标记，这时无需暂停用户线程</p></li><li><p>并发标记之后，会有重新标记阶段解决漏标问题，此时需要暂停用户线程。</p></li><li><p>这些都完成后就知道了老年代有哪些存活对象，随后进入混合收集阶段。此时不会对所有老年代区域进行回收，而是根据暂停时间目标优先回收价值高（存活对象少）的区域（这也是Gabage First名称的由来）。</p></li></ul><p>Mixed Collection(混合垃圾回收)</p><p>复制完成，内存得到释放。进入下一轮的新生代回收、并发标记、混合收集</p><p>其中大对象如果一个固定区域不够的话，会分配一个连续的空间给他</p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305180830.png" alt="image.png"></p><hr><h4 id="强引用、软引用、弱引用和虚引用的区别" tabindex="-1">强引用、软引用、弱引用和虚引用的区别？ <a class="header-anchor" href="#强引用、软引用、弱引用和虚引用的区别" aria-label="Permalink to &quot;强引用、软引用、弱引用和虚引用的区别？&quot;">​</a></h4><ul><li>强引用</li><li>软引用</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305180957.png" alt="image.png"></p><p>弱引用</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181051.png" alt="image.png"></p><p>虚引用</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181207.png" alt="image.png"></p><p>总结</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181232.png" alt="image.png"></p><h3 id="jvm-实践" tabindex="-1">JVM 实践 <a class="header-anchor" href="#jvm-实践" aria-label="Permalink to &quot;JVM 实践&quot;">​</a></h3><h4 id="jvm-调优参数可以在哪里设置参数值" tabindex="-1">JVM 调优参数可以在哪里设置参数值 <a class="header-anchor" href="#jvm-调优参数可以在哪里设置参数值" aria-label="Permalink to &quot;JVM 调优参数可以在哪里设置参数值&quot;">​</a></h4><p>一般是分为两种情况，一种是 tomcat 的 war 包，还有一种是 SpringBoot 打包的 Jar 包</p><p>War 包</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181344.png" alt="image.png"></p><p>Jar 包</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181440.png" alt="image.png"></p><p>总结：</p><p>JVM 调优的参数可以在那里设置参数值</p><ul><li>war 包部署在 tomcat 中设置 <ul><li>修改 TOMCAT_HOME/bin/catalina.sh 文件</li></ul></li><li>jar 包部署在启动参数设置 <ul><li>java -Xms512m -Xmx1024m -jar xxxx.jar</li></ul></li></ul><h4 id="jvm-调优参数有哪些" tabindex="-1">JVM 调优参数有哪些 <a class="header-anchor" href="#jvm-调优参数有哪些" aria-label="Permalink to &quot;JVM 调优参数有哪些&quot;">​</a></h4><p>官网参考： <a href="https://www.oracle.com/java/technologies/javase/vmoptions-jsp.html" target="_blank" rel="noreferrer">https://www.oracle.com/java/technologies/javase/vmoptions-jsp.html</a></p><p>一般不会用到很多</p><p>对于 JVM调优，主要就是调整年轻代、老年代、元空间的内存空间大小及使用的垃圾回收器类型。</p><ul><li>设置堆空间大小 <ul><li>-Xms 设置堆的初始化大小</li><li>-Xmx：设置堆的最大大小</li></ul></li><li>虚拟机栈的设置</li><li>年轻代中Eden区和两个Survivor区的大小比例</li><li>年轻代晋升老年代阈值</li><li>设置垃圾回收收集器</li></ul><p>设置堆空间大小</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181900.png" alt="image.png"></p><p>虚拟机栈的设置</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305181941.png" alt="image.png"></p><p>年轻代中 Eden 区和 两个 Survivor 区的大小比例</p><ul><li>默认 Eden区：From：To = 8：1：1</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182044.png" alt="image.png"></p><p>设置垃圾回收收集器</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182124.png" alt="image.png"></p><p>总结</p><p>用的 JVM 调优的参数都有哪些？</p><ul><li>设置堆空间大小</li><li>虚拟机栈的设置</li><li>年轻代中 Eden 区和两个 Survivor 区的大小比例</li><li>年轻代晋升老年代阈值</li><li>设置垃圾回收收集器</li></ul><h4 id="说一下-jvm-调优的工具" tabindex="-1">说一下 JVM 调优的工具 <a class="header-anchor" href="#说一下-jvm-调优的工具" aria-label="Permalink to &quot;说一下 JVM 调优的工具&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182245.png" alt="image.png"></p><p>具体待实践使用一下</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182346.png" alt="image.png"></p><ul><li>jmap</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182527.png" alt="image.png"></p><ul><li>jstat</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182633.png" alt="image.png"></p><ul><li>调优工具：jconsole</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182745.png" alt="image.png"></p><ul><li>调优工具 VisualVM</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305182942.png" alt="image.png"></p><p>查看运行中的 dump</p><p>Dump文件是进程的内存镜像。可以把程序的执行状态通过调试器保存到dump文件中</p><p><a href="https://zhuanlan.zhihu.com/p/372721732" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/372721732</a></p><p>可以使用 JProfiler 工具来查看</p><p>或者</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305183605.png" alt="image.png"></p><p>总结：略</p><h4 id="java-内存泄漏的排查思路" tabindex="-1">Java 内存泄漏的排查思路 <a class="header-anchor" href="#java-内存泄漏的排查思路" aria-label="Permalink to &quot;Java 内存泄漏的排查思路&quot;">​</a></h4><p>Java 的内存溢出有三个方向：栈、元空间和堆，栈一般是递归调用造成，堆的情况是平时最多的时候，一般考察也是问堆内存溢出怎么排查。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305183716.png" alt="image.png"></p><p>排查的话，提供一种方法：生成 dump 文件，然后分析这个 dump 文件</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305183831.png" alt="image.png"></p><p>生成 dump 文件：</p><ul><li>一般是设置 JVM 参数，有时候程序是直接闪退挂了，不太可能让你运行的时候使用 jmap 命令（使用 vm 参数获取 dump 文件）</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305184231.png" alt="image.png"></p><p>分析 dump 文件</p><ul><li>1、打开 VisualVM</li><li>2、选择：文件 → 装入 → （选择文件） → 打开</li><li>3、概要 → 堆转储</li><li>4、通过查看堆信息的情况，可以大概定位内存谥出是哪行代码出了问题</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305184450.png" alt="image.png"></p><p>总结：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305184724.png" alt="image.png"></p><h4 id="cpu-飙高排查思路" tabindex="-1">CPU 飙高排查思路 <a class="header-anchor" href="#cpu-飙高排查思路" aria-label="Permalink to &quot;CPU 飙高排查思路&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305185105.png" alt="image.png"></p><p>参考： <a href="https://www.bilibili.com/video/BV1yT411H7YK/?p=134&amp;spm_id_from=pageDriver&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yT411H7YK/?p=134&amp;spm_id_from=pageDriver&amp;vd_source=6a019ecccfe7d8f62b9a3fe99c723bd0</a></p><p>分析一下这个过程</p><ul><li>1、使用<code>top</code>命令查看CPU使用情况，确认问题的存在。</li><li>2、在<code>top</code>命令输出中，找到CPU使用率最高的Java进程，记下它的PID。比如，Java进程的PID为12345。</li><li>3、使用<code>jstack</code>命令导出Java进程的线程堆栈信息到文件。</li><li>4、找出CPU使用率最高的线程</li></ul><hr><p><strong>查看进程中的线程信息</strong></p><p>首先，使用<code>ps</code>、<code>top</code>、或<code>jps</code>（Java Virtual Machine Process Status Tool）命令找到Java进程的PID（Process ID）</p><p>使用<code>top</code>命令以线程模式运行，指定Java进程的PID：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top -H -p 12345</span></span></code></pre></div><p>这将显示进程<code>12345</code>中所有线程的CPU使用情况（切换到<code>top</code>命令的线程视图，查看高CPU使用的线程。）</p><blockquote><p>将线程ID转换为16进制</p></blockquote><p>Linux系统中<code>top</code>命令显示的是线程的PID（实际上是轻量级进程ID，LWP ID），需要将其转换为16进制，以匹配<code>jstack</code>输出中的线程ID。</p><p>假设线程ID是<code>6789</code>，可以使用<code>printf</code>命令进行转换：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf &quot;%x\\n&quot; 6789</span></span></code></pre></div><p>输出将是线程ID的16进制表示。</p><blockquote><p>获取线程堆栈</p></blockquote><p>使用<code>jstack</code>命令导出Java进程的线程堆栈信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jstack 12345 &gt; threadDump.txt</span></span></code></pre></div><p>这将把进程<code>12345</code>的所有线程堆栈信息输出到<code>threadDump.txt</code>文件中。</p><p>在<code>threadDump.txt</code>文件中，查找转换为16进制的线程ID对应的堆栈信息。这通常以<code>nid=0x</code>开头，后跟线程的16进制ID。</p><p>定位到高CPU使用线程的堆栈信息后，分析它正在执行的代码。查找该堆栈中的Java方法和类，特别关注自己的应用程序代码。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240305190353.png" alt="image.png"></p><hr><h4 id="讲一下当时jvm-异常是怎么排查出来的-以及怎么解决的" tabindex="-1">讲一下当时JVM 异常是怎么排查出来的，以及怎么解决的 <a class="header-anchor" href="#讲一下当时jvm-异常是怎么排查出来的-以及怎么解决的" aria-label="Permalink to &quot;讲一下当时JVM 异常是怎么排查出来的，以及怎么解决的&quot;">​</a></h4>',238)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
